import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CFuv5BrO.js";const g=JSON.parse('{"title":"自研与集成边界","description":"Hearth 自研核心、适配层、直接集成与只学习不集成的边界；以及 Codex 集成方式。","frontmatter":{"title":"自研与集成边界","description":"Hearth 自研核心、适配层、直接集成与只学习不集成的边界；以及 Codex 集成方式。","outline":[2,3]},"headers":[],"relativePath":"reference/build-vs-integrate.md","filePath":"reference/build-vs-integrate.md","lastUpdated":1793752688000}'),n={name:"reference/build-vs-integrate.md"};function l(i,e,s,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<p class="eyebrow">BUILD VS. INTEGRATE</p><h1 id="自研与集成边界" tabindex="-1">自研与集成边界 <a class="header-anchor" href="#自研与集成边界" aria-label="Permalink to &quot;自研与集成边界&quot;">​</a></h1><p class="lead">Hearth 自己做核心控制与记忆，直接集成模型、Codex、浏览器、文档解析和 Sandbox 内核。边界越清楚，产品越不容易变成集成拼盘。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>Hearth 自己做“指挥系统、账本、门禁和验收”，集成“模型、沙箱、浏览器、文档解析器和外部 API”。</p><p>这里的“自研”主要指产品和核心逻辑自研，不是所有底层库都从零写。例如事件日志协议自研，但底层数据库用 SQLite；前端体验自研，但使用 React/Vite。</p><h2 id="交付边界-自研核心不等于最后才做" tabindex="-1">交付边界：自研核心不等于最后才做 <a class="header-anchor" href="#交付边界-自研核心不等于最后才做" aria-label="Permalink to &quot;交付边界：自研核心不等于最后才做&quot;">​</a></h2><p>“自研”描述责任归属，不描述开发顺序。Hearth 不会先把控制面、Harness、Memory 和所有执行器做完，最后再补前端。</p><ul><li><strong>前端属于核心自研</strong>：任务卡、审批、产物、恢复和手机入口是产品差异化的可见部分，不是后端完成后的包装层。</li><li><strong>Stage 0 就有原型</strong>：用可点击 Web 原型验证产品叙事、状态和主动作，即使数据是模拟的。</li><li><strong>Stage 1 尽早交付 MVP</strong>：在一个窄任务族上同时交付真实 Web、持久状态、Codex 执行、产物、审批演练和失败恢复。</li><li><strong>每个增量都是纵向切片</strong>：用户结果、界面、后端、执行器、验证和恢复一起出现；只有 CLI 或日志的能力不算阶段完成。</li><li><strong>自研/集成边界不因 MVP 改变</strong>：MVP 仍然不自研模型、容器内核或完整 Agent 框架，但必须自研任务控制、验证、审批、恢复和用户界面。</li></ul><p>具体增量顺序见主路线图第 25 章或分册 <code>Hearth_路线图分册/09_从0到100开发计划.md</code>。</p><h2 id="一、hearth-自己做的核心部分" tabindex="-1">一、Hearth 自己做的核心部分 <a class="header-anchor" href="#一、hearth-自己做的核心部分" aria-label="Permalink to &quot;一、Hearth 自己做的核心部分&quot;">​</a></h2><p>这些是文档认定的产品护城河，不能外包：</p><ul><li><p><strong>Control Plane 控制面</strong><br> 决定一个事件要不要处理、是否创建任务、是否允许执行、用哪个执行器、花多少预算、什么时候找你审批、失败后重试还是转人工。</p></li><li><p><strong>Durable Harness 持久执行层</strong><br> Task、Ticket、Run、任务图、依赖关系、lease、单写者、fencing token、检查点、重试、取消和崩溃恢复。</p></li><li><p><strong>Event Log 事件日志与投影</strong><br> 只追加的事实源、schema、migration、任务状态投影、审计和重放。这里自研的是协议和语义，不是数据库引擎。</p></li><li><p><strong>Policy、Mandate、Capability、Approval</strong><br> 长期规则、单次授权、资源范围和期限、风险分级、审批绑定、权限回收。</p></li><li><p><strong>外部副作用控制</strong><br> Effect Preview、outbox、幂等键、Effect Dispatcher、Receipt、对账和死信处理。这是“不会重复发邮件、不会重复付款”的核心。</p></li><li><p><strong>Context Compiler 与 Token Governor</strong><br> 组装最小 Task Pack、选择模型阶梯、控制上下文、缓存、预算、成本归因和异常停止。</p></li><li><p><strong>Memory OS</strong><br> 五类记忆、来源和可信度、冲突、敏感度、召回、遗忘、多设备同步和记忆 UI。</p></li><li><p><strong>Evolution OS</strong><br> 轨迹挖掘、技能候选、评估集、Shadow、Canary、晋升、权限检查和回滚。</p></li><li><p><strong>Execution Gateway 的控制逻辑</strong><br> Workspace 生命周期、挂载与文件权限、网络白名单和 egress、Capability、配额、快照、恢复、审计和接管。</p></li><li><p><strong>Credential Broker</strong><br> 长期密钥存储、短期凭据发放、按任务和账户限定、使用审计和撤销，保证模型看不到原始密码和 refresh token。</p></li><li><p><strong>Personal Gateway 与体验层</strong><br> 渠道事件归一化、去重、设备注册、能力目录、注意力收件箱、任务卡、审批界面、产物中心、手机入口和接管流程。</p></li><li><p><strong>验证器与评估体系</strong><br> 测试、diff、引用检查、表格检查、邮件收件人检查、网页状态检查、故障注入和轨迹重放。</p></li><li><p><strong>Native Runtime 的薄执行层</strong><br> 短任务工具循环、session tree、steering、compaction 和升级到 Codex 的逻辑；模型本身不自研。</p></li></ul><h2 id="二、hearth-自研-适配层-但底层用现成能力" tabindex="-1">二、Hearth 自研“适配层”，但底层用现成能力 <a class="header-anchor" href="#二、hearth-自研-适配层-但底层用现成能力" aria-label="Permalink to &quot;二、Hearth 自研“适配层”，但底层用现成能力&quot;">​</a></h2><p>这类不是完全自己做，也不是简单调用，而是自己控制接口、策略、验证和恢复：</p><ul><li><p><strong>Codex Executor</strong><br> 集成 Codex，但 Hearth 自己做版本锁定、Task Pack、工作区隔离、结构化输出、超时取消、验证和失败分类。</p></li><li><p><strong>Browser Executor</strong><br> 浏览器内核和自动化用 Playwright；Hearth 自己做登录态边界、网页策略、提示词注入防护、验证、截图和人工接管。</p></li><li><p><strong>Connector Executor</strong><br> 邮件、日历、云盘、IM 等接入官方 API 或 MCP；Hearth 自己做统一的 <code>Source/Effect</code> 协议、权限、限流、幂等、回执和对账。</p></li><li><p><strong>Document/Data Executor</strong><br> 解析、OCR、格式转换和表格处理用成熟 Python 库；Hearth 自己做管道调度、最小上下文提取、结果验证和与 Codex 的分工。</p></li><li><p><strong>Sandbox</strong><br> 用 Docker、OCI 容器或微虚拟机；Hearth 自己做 Sandbox Provider 接口、工作区生命周期、网络白名单、凭据隔离和回收。</p></li><li><p><strong>GUI Executor</strong><br> 使用操作系统提供的可访问性树、截图、键鼠和窗口能力；Hearth 自己做 agentd、任务边界、验证、恢复和人工接管。</p></li><li><p><strong>可观测性</strong><br> 用 OpenTelemetry；Hearth 自己做任务轨迹语义、Token 归因和用户可见的审计视图。</p></li></ul><h2 id="三、明确直接集成别人的部分" tabindex="-1">三、明确直接集成别人的部分 <a class="header-anchor" href="#三、明确直接集成别人的部分" aria-label="Permalink to &quot;三、明确直接集成别人的部分&quot;">​</a></h2><p>文档明确不重写这些成熟基础设施：</p><ul><li><strong>模型</strong>：OpenAI、Anthropic、本地模型或其他模型 API，采用 BYOM；不训练基础模型，也不自研推理引擎。</li><li><strong>Codex</strong>：目前唯一接入的外部 Agent，可承担代码、研究、文档、表格和复杂工作区任务。</li><li><strong>Playwright</strong>：浏览器自动化引擎。</li><li><strong>文档解析与转换库</strong>：PDF、Office、OCR、表格处理等。</li><li><strong>邮件、日历、云盘等官方 API 或 MCP</strong>：真实外部系统连接。</li><li><strong>容器/微虚拟机/Sandbox 内核</strong>：Docker 起步，高风险任务用更强隔离。</li><li><strong>OpenTelemetry</strong>：可观测性基础设施。</li><li><strong>常规技术栈</strong>：TypeScript、Node.js、SQLite、React、Vite、Fastify/Hono、Zod、Python sidecar 等。</li></ul><h2 id="四、只学习、不集成、不作为产品底座的项目" tabindex="-1">四、只学习、不集成、不作为产品底座的项目 <a class="header-anchor" href="#四、只学习、不集成、不作为产品底座的项目" aria-label="Permalink to &quot;四、只学习、不集成、不作为产品底座的项目&quot;">​</a></h2><p>这个边界非常重要：</p><ul><li><strong>OpenClaw</strong>：学习 Gateway、渠道、设备节点、注意力入口和常驻模式，不 fork，也不作为运行时依赖。</li><li><strong>Hermes</strong>：学习记忆预算、记忆约束、技能沉淀和进化闭环，不采用无界自修改。</li><li><strong>DeerFlow</strong>：学习 Harness/App 分层、Run 生命周期和 thread 隔离，不引入重型框架耦合。</li><li><strong>Pi / Maka</strong>：学习 session tree、steering、compaction 和事件日志，不复制完整框架。</li><li><strong>OpenSandbox / OpenBot</strong>：学习隔离、快照、takeover 和 receipt，不复制完整产品。</li><li><strong>OpenMuse / OpenDots</strong>：学习 durable job、checkpoint、lease 和低打扰体验。</li><li><strong>Codex</strong>：比较特殊，既学习其工作区执行模式，也实际集成。</li></ul><p>所以，当前文档中：</p><blockquote><p>Hearth 没有把 OpenClaw、Hermes、DeerFlow 作为运行时集成，也没有把它们当作产品底座。当前唯一接入的外部 Agent 是 Codex；其他项目主要是参考模式和学习目标。</p></blockquote><h2 id="最后用一句话记住边界" tabindex="-1">最后用一句话记住边界 <a class="header-anchor" href="#最后用一句话记住边界" aria-label="Permalink to &quot;最后用一句话记住边界&quot;">​</a></h2><blockquote><p>Hearth 自研的是“任务如何被授权、调度、验证、恢复和记住”；集成的是“完成任务所需的成熟发动机和工具”。</p></blockquote><p>它不想重新发明模型、容器、浏览器和文档解析器，而是想把它们组织成一套可控、可审计、可恢复的个人 Agent OS。</p><h2 id="原文依据" tabindex="-1">原文依据 <a class="header-anchor" href="#原文依据" aria-label="Permalink to &quot;原文依据&quot;">​</a></h2><ul><li>Build vs Integrate：完整主文档第 280 行</li><li>Sandbox 边界：<code>:2019</code></li><li>推荐技术栈：<code>:3848</code></li><li>最终判断：<code>:4256</code></li></ul><hr><h2 id="五、hearth-与-openclaw-的真实区别" tabindex="-1">五、Hearth 与 OpenClaw 的真实区别 <a class="header-anchor" href="#五、hearth-与-openclaw-的真实区别" aria-label="Permalink to &quot;五、Hearth 与 OpenClaw 的真实区别&quot;">​</a></h2><h3 id="先给结论" tabindex="-1">先给结论 <a class="header-anchor" href="#先给结论" aria-label="Permalink to &quot;先给结论&quot;">​</a></h3><p><strong>今天能直接使用的产品能力，OpenClaw 明显领先 Hearth；Hearth 目前仍是一份路线图，不是一个已经交付的系统。</strong></p><p>因此，不能说“Hearth 已经比 OpenClaw 强”，也不能说“Hearth 天然是 OpenClaw 的上一层”。更准确的说法是：</p><blockquote><p><strong>OpenClaw 已经是一个成熟的个人助手 Gateway 和控制面；Hearth 想做一个以“任务与承诺”为核心对象的、更严格的任务控制层。</strong></p></blockquote><p>两者的差别不是“谁的功能列表更长”，而是“谁对什么负责”：</p><ul><li>OpenClaw 主要对<strong>会话、渠道、个人助手体验和常驻服务</strong>负责；</li><li>Hearth 主要想对<strong>任务是否被正确授权、是否真的完成、外部副作用是否可证明、失败后是否可恢复</strong>负责。</li></ul><p>这两个方向有大量重叠。OpenClaw 已经有记忆、审计、审批、沙箱、队列、重启恢复和多设备入口，所以这些能力不能再说成 Hearth 独有。</p><h3 id="两者到底差在哪" tabindex="-1">两者到底差在哪 <a class="header-anchor" href="#两者到底差在哪" aria-label="Permalink to &quot;两者到底差在哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>OpenClaw</th><th>Hearth 的设计目标</th></tr></thead><tbody><tr><td>核心对象</td><td>会话、渠道消息、Agent Run、常驻个人助手</td><td>Event → Task → Ticket → Run，任务和承诺是一等对象</td></tr><tr><td>产品重心</td><td>在用户已有的聊天渠道里提供随时可用的个人助手</td><td>管理长任务、跨执行器协作、授权、预算和验收</td></tr><tr><td>交互方式</td><td>聊天、渠道消息、Control UI、移动端和桌面节点</td><td>任务卡、审批、产物中心、收件箱和手机接管</td></tr><tr><td>记忆</td><td>已实现分层记忆、来源追踪、信任边界、Dreaming、用户模型、standing intents</td><td>计划做带来源、冲突、敏感度、遗忘和多设备同步的 Memory OS；功能上与 OpenClaw 有明显重叠</td></tr><tr><td>审计</td><td>已实现有界、元数据级的审计账本、执行身份、审批决策记录和消息生命周期审计；其文档明确说明账本不是无损记录，也不是授权证据</td><td>计划把 Event Log 作为事实源，并把 Effect、审批、执行和验收绑定到同一条任务轨迹</td></tr><tr><td>外部副作用</td><td>对 <code>send</code>、<code>agent</code> 等有副作用的调用要求幂等键，并有消息投递审计</td><td>进一步把外部副作用建模为类型化 Effect，经 outbox、幂等键、Dispatcher 和 Receipt 对账</td></tr><tr><td>完成判定</td><td>有 Run 状态、审计和结果；但“任务是否真的完成”仍主要依赖执行流程和上层判断</td><td>计划把 Verifier 作为完成门槛，不能只相信执行器说“已完成”</td></tr><tr><td>沙箱</td><td>已实现 Docker、Podman、SSH、OpenShell、Crabbox 等后端</td><td>计划只自研 Sandbox Provider 接口、生命周期、网络出口和凭据隔离，底层复用成熟沙箱</td></tr><tr><td>恢复</td><td>已有队列、session controller、watchdog、重启恢复和自动续跑</td><td>计划用 Event Log、lease、fencing、checkpoint、retry 和人工接管来做任务级恢复</td></tr><tr><td>生态和渠道</td><td>20+ 聊天渠道、桌面/移动节点、插件、技能和 ClawHub</td><td>当前路线图只有手机优先 PWA，尚未形成渠道和插件生态</td></tr><tr><td>成熟度</td><td>有可运行代码、文档、安装器、测试和真实使用路径</td><td>仍是架构与实施路线图，尚无同等程度的可运行产品证据</td></tr></tbody></table><h3 id="为什么容易误以为-hearth-是-上一层" tabindex="-1">为什么容易误以为 Hearth 是“上一层” <a class="header-anchor" href="#为什么容易误以为-hearth-是-上一层" aria-label="Permalink to &quot;为什么容易误以为 Hearth 是“上一层”&quot;">​</a></h3><p>因为两者都在做“控制”，但控制的对象不同：</p><ul><li>OpenClaw 的控制面主要控制 <strong>Gateway、会话、渠道、执行身份和消息投递</strong>；</li><li>Hearth 想控制的是 <strong>任务契约、授权范围、上下文预算、外部副作用和验收结果</strong>。</li></ul><p>如果未来 Hearth 把 OpenClaw 作为一个 Gateway 或 Executor 接入，那么可以形成这样的关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hearth：任务、授权、预算、验收、副作用回执</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>OpenClaw：渠道、会话、个人助手运行时、设备节点</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>Codex / 其他执行器：实际完成某一段工作</span></span></code></pre></div><p>在这种特定架构下，Hearth 才是“任务控制层”，OpenClaw 是它下面的个人助手运行时。但必须注意：</p><ol><li>这不是当前路线图的实现；</li><li>当前路线图只接入 Codex，没有把 OpenClaw 作为运行时组件；</li><li>OpenClaw 自己已经可以接入 Codex 等多种 Agent Harness，所以“接入 Codex”并不能让 Hearth 天然高 OpenClaw 一层；</li><li>只有在 Hearth 真正掌握任务授权、预算、副作用和验收，并且 OpenClaw 只负责渠道与执行时，上下层关系才成立。</li></ol><p>所以，“上一层控制面”应改成：</p><blockquote><p><strong>Hearth 想做任务与承诺层的控制面，而不是 OpenClaw 的天然上级产品。它必须通过明确的接口、权限和回执边界，才有资格成为 OpenClaw 之上的一层。</strong></p></blockquote><h3 id="hearth-要在什么条件下才算真的更强" tabindex="-1">Hearth 要在什么条件下才算真的更强 <a class="header-anchor" href="#hearth-要在什么条件下才算真的更强" aria-label="Permalink to &quot;Hearth 要在什么条件下才算真的更强&quot;">​</a></h3><p>不能靠“功能更多”证明更强，只能靠可验证的差异。至少要通过下面四类测试：</p><ol><li><strong>副作用测试</strong>：任务执行到一半崩溃、重试或重启后，邮件不会重复发、订单不会重复提交、文件不会重复覆盖，并能用 Receipt 对账。</li><li><strong>完成测试</strong>：执行器声称完成后，Hearth 能通过测试、diff、引用、文件结构、网页状态或业务规则证明结果真的满足任务定义。</li><li><strong>权限测试</strong>：执行器被提示词注入或试图越权时，无法拿到超出 Task Mandate 的凭据、目录、网络和工具。</li><li><strong>成本测试</strong>：在相同任务集上，Hearth 的 Token、延迟和人工注意力成本不高于直接使用 OpenClaw 或直接使用 Codex，并且有可解释的归因。</li></ol><p>如果这四件事没有做出来，Hearth 就只是一个更晚出现、更复杂的 OpenClaw；如果做出来了，它才有资格说自己是在“任务可靠性”这一层更强。</p><h2 id="六、codex-真的可以集成吗-能使用它的全部能力吗" tabindex="-1">六、Codex 真的可以集成吗，能使用它的全部能力吗 <a class="header-anchor" href="#六、codex-真的可以集成吗-能使用它的全部能力吗" aria-label="Permalink to &quot;六、Codex 真的可以集成吗，能使用它的全部能力吗&quot;">​</a></h2><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p><strong>技术上可以集成，而且路线图把 Codex 作为第一个外部 Executor 是可行的。</strong></p><p><strong>但不能说“可以使用 Codex 的全部能力”。</strong> 你只能使用 Codex 公开暴露的、当前账户和版本允许的、且接口相对稳定的那一部分能力。</p><p>Codex 是执行器，不是 Hearth 的权限中心、任务数据库、记忆中心或外部副作用网关。</p><h3 id="已经确认可用的集成入口" tabindex="-1">已经确认可用的集成入口 <a class="header-anchor" href="#已经确认可用的集成入口" aria-label="Permalink to &quot;已经确认可用的集成入口&quot;">​</a></h3><p>以本机 <code>codex-cli 0.163.0</code> 和 <code>@openai/codex-sdk 0.166.0</code> 为核对基准：</p><ul><li><strong><code>codex exec</code></strong>：非交互执行，适合 Hearth 的第一阶段接入。 <ul><li><code>--json</code>：输出 JSONL 事件流；</li><li><code>--output-schema</code>：约束最终结构化输出；</li><li><code>-C</code>：指定工作目录；</li><li><code>--sandbox read-only | workspace-write | danger-full-access</code>：沙箱模式；</li><li><code>-a / --ask-for-approval</code>：全局审批策略，需要放在 <code>exec</code> 之前；<code>codex exec</code> 子命令本身不接受该参数；</li><li><code>--ephemeral</code>：不持久化会话文件；</li><li><code>--skip-git-repo-check</code>：允许非 Git 目录；</li><li><code>--add-dir</code>：增加可写目录；</li><li><code>-i</code>：附加图片；</li><li><code>-o</code>：把最后一条消息写入文件；</li><li><code>resume</code>、<code>fork</code>、<code>review</code>：恢复、分叉和代码审查。</li></ul></li><li><strong><code>@openai/codex-sdk</code></strong>：TypeScript SDK，本质上是启动 Codex CLI，通过 stdin/stdout 交换 JSONL。 <ul><li><code>startThread()</code> / <code>resumeThread()</code>；</li><li><code>run()</code> / <code>runStreamed()</code>；</li><li>结构化输出、图片输入、工作目录、沙箱模式、审批策略、模型和推理强度；</li><li>命令执行、文件修改、MCP 工具调用、网页搜索、todo 和 usage 事件。</li></ul></li><li><strong><code>codex app-server</code></strong>：实验性接口，支持 stdio、Unix socket、WebSocket，可生成 TypeScript 绑定和 JSON Schema。适合需要细粒度流式事件和审批的深度集成，但必须按实验性接口对待。</li><li><strong><code>codex exec-server</code></strong>：实验性的独立远程执行服务。</li><li><strong><code>codex cloud</code></strong>：实验性的 Codex Cloud 任务接口，依赖账户和 Cloud 能力。</li><li><strong>MCP / 插件</strong>：可以通过 <code>codex mcp</code> 和 <code>codex plugin</code> 管理外部工具与插件。</li></ul><h3 id="为什么不能说-全部能力" tabindex="-1">为什么不能说“全部能力” <a class="header-anchor" href="#为什么不能说-全部能力" aria-label="Permalink to &quot;为什么不能说“全部能力”&quot;">​</a></h3><p>以下限制是结构性的，不是接入层偷懒：</p><ol><li><strong>账户和计划限制</strong>：模型、Cloud、Web Search、组织策略、地区可用性都受 OpenAI 账户和权限约束。</li><li><strong>版本限制</strong>：CLI、SDK 和 app-server 的协议可能变化；本机 CLI 与 SDK 版本已经不一致，不能假设任意版本互相兼容。</li><li><strong>实验性接口限制</strong>：<code>app-server</code>、<code>exec-server</code>、<code>cloud</code> 都明确标注实验性，不保证稳定。</li><li><strong>SDK 不等于完整平台</strong>：SDK 是 CLI 的包装层，不覆盖 Codex 桌面端、账户管理、计费管理和全部 Cloud/UI 能力。</li><li><strong>Codex 不提供 Hearth 的治理能力</strong>：Mandate、Capability、Credential Broker、Effect outbox、幂等投递、Receipt 对账和 Verifier 都不在 Codex 内。</li><li><strong>会话持久化不等于任务事件日志</strong>：Codex 的 thread/session 可以恢复，但不能替代 Hearth 的事实源、任务图和审计语义。</li><li><strong>MCP 工具不等于安全工具</strong>：Codex 能调用 MCP，不代表应该把邮件、日历、付款等高风险工具直接交给它。</li><li><strong><code>danger-full-access</code> 不是默认选项</strong>：只有在一次性、强隔离、可销毁的沙箱里才可以使用；正常任务应使用最小目录和最小网络权限。</li></ol><h3 id="推荐的接入架构" tabindex="-1">推荐的接入架构 <a class="header-anchor" href="#推荐的接入架构" aria-label="Permalink to &quot;推荐的接入架构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hearth Task / Ticket</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Context Compiler 生成最小 Task Pack</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Codex Adapter：版本检查、工作区准备、权限注入、超时控制</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>隔离 Workspace 中的 codex exec --json --output-schema</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>JSONL 事件 + 结构化结果 + 产物清单</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Hearth Verifier：测试、diff、引用、文件检查、业务规则</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>接受 / 重试 / 回滚 / 人工接管</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>需要外部副作用时，由 Hearth Connector 走 outbox、幂等键和 Receipt</span></span></code></pre></div><p>关键点是：<strong>Codex 可以在沙箱内写文件、运行命令和调用受控工具；但邮件发送、日历修改、付款、发布等外部副作用必须回到 Hearth 的 Effect 通道，不能由 Codex 直接完成。</strong></p><h3 id="推荐的三阶段落地" tabindex="-1">推荐的三阶段落地 <a class="header-anchor" href="#推荐的三阶段落地" aria-label="Permalink to &quot;推荐的三阶段落地&quot;">​</a></h3><p><strong>阶段一：先跑通单次任务</strong></p><ul><li>用 <code>codex exec --json --output-schema</code>；</li><li>每个 Run 使用独立临时工作区；</li><li>只挂载任务需要的目录；</li><li>设置超时、取消和进程树回收；</li><li>解析 JSONL，保存事件、usage 和最终结构化结果；</li><li>用 Hearth 自己的 Verifier 判断是否成功。</li></ul><p><strong>阶段二：增加多轮和恢复</strong></p><ul><li>保存 Codex thread id，但以 Hearth Event Log 为权威状态；</li><li>需要多轮时使用 <code>resume</code>；</li><li>任务失败后先分类：模型失败、工具失败、验证失败、权限失败、环境失败；</li><li>对可重试任务使用幂等键，避免重复副作用。</li></ul><p><strong>阶段三：再评估 app-server</strong></p><ul><li>只有确实需要细粒度流式事件、原生审批转发或长期连接时，才引入 <code>app-server</code>；</li><li>锁定 CLI 与协议版本；</li><li>为协议生成和事件字段建立契约测试；</li><li>对未知事件保持向前兼容，不能因为新增字段崩溃。</li></ul><h3 id="接入-codex-的硬性规则" tabindex="-1">接入 Codex 的硬性规则 <a class="header-anchor" href="#接入-codex-的硬性规则" aria-label="Permalink to &quot;接入 Codex 的硬性规则&quot;">​</a></h3><ul><li><strong>锁定版本</strong>：记录 CLI 版本、SDK 版本和协议版本，升级前跑契约测试；</li><li><strong>最小工作区</strong>：一个 Run 一个 workspace，任务结束回收；</li><li><strong>最小环境变量</strong>：不把长期密钥、浏览器 Cookie 和无关凭据传给子进程；</li><li><strong>最小网络出口</strong>：默认关闭或白名单，只允许任务需要的域名；</li><li><strong>结构化输出</strong>：要求 <code>--output-schema</code>，不要解析自然语言来判断成功；</li><li><strong>独立验证</strong>：Codex 说完成不算完成，必须通过 Hearth Verifier；</li><li><strong>副作用隔离</strong>：Codex 不直接持有邮件、日历、付款和发布权限；</li><li><strong>可取消</strong>：超时和用户取消要终止整个进程树，而不只是停止读取输出；</li><li><strong>日志脱敏</strong>：JSONL、命令输出和错误信息都可能包含敏感数据，写入 Event Log 前要脱敏；</li><li><strong>临时会话优先</strong>：一次性任务使用 <code>--ephemeral</code>；需要恢复时再显式保存 thread id。</li></ul><h3 id="最终判断" tabindex="-1">最终判断 <a class="header-anchor" href="#最终判断" aria-label="Permalink to &quot;最终判断&quot;">​</a></h3><p>Codex 可以作为 Hearth 的“高能力工作区执行器”，而且现在就能做第一阶段集成。但正确的目标不是“把 Codex 的全部能力嵌进来”，而是：</p><blockquote><p><strong>定义一个 Hearth 自己能验证、能限权、能恢复、能计费的 Codex 能力子集，并把它封装成稳定的 Executor 合约。</strong></p></blockquote><p>这也是 Hearth 与“Codex 套壳”的分界线：套壳把 Codex 当产品；Hearth 把 Codex 当可替换、可治理的执行引擎。</p><h2 id="补充依据" tabindex="-1">补充依据 <a class="header-anchor" href="#补充依据" aria-label="Permalink to &quot;补充依据&quot;">​</a></h2><ul><li>Hearth 的 Codex 定位与 Build vs Integrate：完整主文档第 2.3–2.4 节</li><li>Hearth 最终集成边界：完整主文档第 29.5 节</li><li>MVP 与从 0 到 100 的开发顺序：完整主文档第 25 章</li><li>OpenClaw Gateway、渠道和设备节点：本机 OpenClaw 文档 <code>docs/concepts/architecture.md</code></li><li>OpenClaw 审计账本与执行身份：本机 OpenClaw 文档 <code>docs/gateway/audit.md</code></li><li>OpenClaw 沙箱后端：本机 OpenClaw 文档 <code>docs/gateway/sandboxing.md</code></li><li>OpenClaw 记忆架构：本机 OpenClaw 文档 <code>docs/concepts/memory-architecture.md</code></li><li>OpenClaw 队列与恢复：本机 OpenClaw 文档 <code>docs/concepts/queue.md</code>、<code>docs/gateway/restart-recovery.md</code></li><li>OpenClaw standing intents：本机 OpenClaw 文档 <code>docs/concepts/standing-intents.md</code></li><li>Codex CLI 能力：本机 <code>codex-cli 0.163.0</code> 的 <code>codex exec --help</code>、<code>codex app-server --help</code>、<code>codex exec-server --help</code>、<code>codex cloud --help</code></li><li>Codex SDK 能力：<code>@openai/codex-sdk 0.166.0</code> 的 <code>README.md</code> 与 <code>dist/index.d.ts</code></li></ul><blockquote><p>说明：OpenClaw 的能力以本机文档和源码核对结果为准；Codex 的能力以本机 CLI 和 npm SDK 版本为准。两者都可能继续演进，正式接入前必须重新做版本与接口核验。</p></blockquote>`,83)])])}const u=t(n,[["render",l]]);export{g as __pageData,u as default};
